#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("USAGE\n");
        return 0;
    }
    if (strcmp(argv[1], "escape") == 0) {
        // escape mode
        char *str = argv[2];
        int len = strlen(str);
        for (int i = 0; i < len; i++) {
            if (str[i] == '\\') {
                printf("\\\\");
            } else if (str[i] == '\n') {
                printf("\\n");
            } else if (str[i] == '\t') {
                printf("\\t");
            } else {
                printf("%c", str[i]);
            }
        }
    } else if (strcmp(argv[1], "unescape") == 0) {
        // unescape mode
        char *str = argv[2];
        int len = strlen(str);
        for (int i = 0; i < len; i++) {
            if (str[i] == '\') {
                i++;
                if (i >= len) break;
                if (str[i] == '\') {
                    printf("\\");
                } else if (str[i] == 'n') {
                    printf("\n");
                } else if (str[i] == 't') {
                    printf("\t");
                } else {
                    printf("%c", str[i]);
                }
            } else {
                printf("%c", str[i]);
            }
        }
    } else {
        printf("INVALID_MODE\n");
    }
    return 0;
}
